AUTO_PICK = re.compile(r'[(]')


def pick_lines(lines, wanted, limit=6):
    out = []
    for n in wanted:
        if 1 <= n <= len(lines):
            out.append(n)
    if out:
        return out
    for i, line in enumerate(lines, start=1):
        s = line.strip()
        if AUTO_PICK.search(s) and not s.startswith('//') and '0x' not in s and not re.match(r'^(int|float|double|_DWORD|char|void) [a-z]', s):
            out.append(i)
            if len(out) >= limit:
                break
    return out


def table_rows(csv_path, access):
    rows = []
    if not csv_path.is_file():
        return rows
    with open(csv_path, encoding='utf-8', newline='') as fh:
        for r in csv.DictReader(fh):
            if r['access'] != access or not r['hex'] or not r['dec']:
                continue
            rows.append(r)
    return rows


def fmt_table(rows):
    if not rows:
        return "None.\n"
    out = ["| hex | dec | type | line | expr |", "|---|---|---|---|---|"]
    seen = set()
    for r in rows:
        key = (r['hex'], r['dec'], r['line'], r['expr'])
        if key in seen:
            continue
        seen.add(key)
        expr = r['expr'].replace('|', '\\|')[:70]
        expr = re.sub(r'0x[0-9A-Fa-f]+', '0x..', expr)
        out.append("| %s | %s | %s | L%s | `%s` |" % (r['hex'], r['dec'], r['width'] or '?', r['line'], expr))
    return "\n".join(out) + "\n"


def main():
    info = json.load(open(CACHE / 'd3_callees_info.json', encoding='utf-8'))
    made = 0
    for name, meta in sorted(info.items()):
        path = FUNCTIONS / ('%s_%08x.c' % (name, meta['addr']))
        lines = path.read_text(encoding='utf-8').splitlines()
        purpose, relevance, wanted, notes = P.get(name, ("Triage map: see source.", "unknown", [], []))
        picked = pick_lines(lines, wanted)
        quote = []
        for n in picked:
            src = lines[n - 1].rstrip()
            if '0x' in src:
                continue
            quote.append('%-4s %s   [L%d]' % ('', src, n))
        csv_path = MAPS / ('offsets_%s.csv' % name)
        callers = ', '.join('`%s`' % c for c in meta['callers']) if meta['callers'] else 'none in the corpus'
        callees = ', '.join('`%s`' % c for c in meta['calls']) if meta['calls'] else 'none (CSV has only CALL rows of other forms or none)'
        txt = []
        txt.append('# map_%s - `%s` (GUESS name)' % (name, name))
        txt.append('')
        txt.append('## Identity')
        txt.append('')
        txt.append('- Address: `0x%08X`; file `functions/%s`; %d lines.' % (meta['addr'], path.name, meta['lines']))
        txt.append('- Signature: `%s`.' % lines[0].strip() if lines else '- Signature: ?')
        txt.append('- Callers (read-only corpus cache): %s.' % callers)
        txt.append('- Callees (from `offsets_%s.csv` CALL rows): %s.' % (name, callees))
        txt.append('- This is a terse phase-3 triage map; the name is a GUESS until reviewed.')
        txt.append('')
        txt.append('## Inputs')
        txt.append('')
        txt.append(fmt_table(table_rows(csv_path, 'R')).rstrip())
        txt.append('')
        txt.append('## Outputs')
        txt.append('')
        txt.append(fmt_table(table_rows(csv_path, 'W')).rstrip())
        txt.append('')
        txt.append('## Constants')
        txt.append('')
        txt.append('Every numeric literal except 0/1 in the quoted source lines below.')
        txt.append('')
        txt.append('## Logic')
        txt.append('')
        txt.append('```')
        txt.extend(quote if quote else ['(no finite quoted lines)'])
        txt.append('```')
        txt.append('')
        txt.append('## Meaning (GUESS)')
        txt.append('')
        txt.append('- GUESS %s' % purpose)
        txt.append('- GUESS AI relevance: %s' % relevance)
        for n in notes:
            txt.append('- %s' % n)
        txt.append('')
        txt.append('## Questions')
        txt.append('')
        txt.append('- None for this triage map; name and meaning stay GUESS.')
        txt.append('')
        (MAPS / ('map_%s.md' % name)).write_text('\n'.join(txt), encoding='utf-8')
        made += 1
    print('maps written: %d' % made)


if __name__ == '__main__':
    main()
